create database sales_Analytics
use sales_Analytics
-->Customers Table Creation
CREATE TABLE Customers (
    Customer_ID VARCHAR(20) PRIMARY KEY,
    Customer_Name VARCHAR(100),
    Gender VARCHAR(20),
    Age_Group VARCHAR(20),
    City VARCHAR(100),
    State VARCHAR(100),
    Country VARCHAR(100),
    Customer_Segment VARCHAR(50),
    Registration_Date DATE
)

-->Products Table Creation
CREATE TABLE Products (
    Product_ID VARCHAR(20) PRIMARY KEY,
    Product_Name VARCHAR(150),
    Category_ID VARCHAR(20),
    Category VARCHAR(100),
    Subcategory VARCHAR(100),
    Brand VARCHAR(100),
    Unit_Cost DECIMAL(12,2),
    Unit_Price DECIMAL(12,2)
)
-->This table will be used for:
-----Product analysis
-----Category analysis
-----Subcategory analysis
-----Brand analysis
-----Cost/profit calculations

-->Stores table Creation
CREATE TABLE Stores (
    Store_ID VARCHAR(20) PRIMARY KEY,
    Store_Name VARCHAR(100),
    Store_Type VARCHAR(50),
    City VARCHAR(100),
    State VARCHAR(100),
    Region VARCHAR(100),
    Manager VARCHAR(100)
)
-->This table will be used for:
---	Store performance
---	Regional performance
---	Store sales
---	Store profitability

-->Salespersons Table Creation
CREATE TABLE Salespersons (
    Salesperson_ID VARCHAR(20) PRIMARY KEY,
    Salesperson_Name VARCHAR(100),
    Department VARCHAR(100),
    Region VARCHAR(100),
    Joining_Date DATE,
    Target_Sales DECIMAL(12,2)
)
-->This table will be used for:
--Salesperson performance
--Salesperson ranking
--Target achievement
--Regional salesperson analysis

-->Payments Table Creation
CREATE TABLE Payments (
    Payment_ID VARCHAR(20) PRIMARY KEY,
    Payment_Method VARCHAR(50),
    Payment_Status VARCHAR(50),
    Payment_Date DATE
)
-->Sales Table Creation
CREATE TABLE Sales (
    Sale_ID VARCHAR(20) PRIMARY KEY,
    Order_ID VARCHAR(20),
    Order_Date DATE,
    Customer_ID VARCHAR(20),
    Product_ID VARCHAR(20),
    Store_ID VARCHAR(20),
    Salesperson_ID VARCHAR(20),
    Quantity INT,
    Unit_Price DECIMAL(12,2),
    Discount DECIMAL(10,4),
    Tax DECIMAL(12,2),
    Shipping_Cost DECIMAL(12,2),
    Payment_ID VARCHAR(20),

    FOREIGN KEY (Customer_ID)
        REFERENCES Customers(Customer_ID),

    FOREIGN KEY (Product_ID)
        REFERENCES Products(Product_ID),

    FOREIGN KEY (Store_ID)
        REFERENCES Stores(Store_ID),

    FOREIGN KEY (Salesperson_ID)
        REFERENCES Salespersons(Salesperson_ID),

    FOREIGN KEY (Payment_ID)
        REFERENCES Payments(Payment_ID)
)

-->Target table Creation
CREATE TABLE Targets (
    Target_ID VARCHAR(20) PRIMARY KEY,
    Month VARCHAR(20),
    Year INT,
    Store_ID VARCHAR(20),
    Salesperson_ID VARCHAR(20),
    Sales_Target DECIMAL(12,2),
    Profit_Target DECIMAL(12,2),

    FOREIGN KEY (Store_ID)
        REFERENCES Stores(Store_ID),

    FOREIGN KEY (Salesperson_ID)
        REFERENCES Salespersons(Salesperson_ID)
)

-->Date Table Creation
CREATE TABLE Date_Dim (
    [Date] DATE PRIMARY KEY,
    [Day] INT,
    [Month] VARCHAR(20),
    Month_Number INT,
    [Quarter] VARCHAR(10),
    [Year] INT,
    Week_Number INT,
    Day_Name VARCHAR(20)
)

