INSERT INTO Date_Dim
(
    [Date],
    [Day],
    [Month],
    Month_Number,
    [Quarter],
    [Year],
    Week_Number,
    Day_Name
)
SELECT
    d AS [Date],
    DAY(d) AS [Day],
    DATENAME(MONTH, d) AS [Month],
    MONTH(d) AS Month_Number,
    'Q' + CAST(DATEPART(QUARTER, d) AS VARCHAR(1)) AS [Quarter],
    YEAR(d) AS [Year],
    DATEPART(WEEK, d) AS Week_Number,
    DATENAME(WEEKDAY, d) AS Day_Name
FROM
(
    SELECT DATEADD(DAY, n, '2025-01-01') AS d
    FROM
    (
        SELECT TOP (731)
            ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) - 1 AS n
        FROM sys.all_objects a
        CROSS JOIN sys.all_objects b
    ) numbers
) dates
WHERE d <= '2026-12-31';

