select * from Targets
select * from customers
select * from products
select * from sales
select * from payments
select * from stores
select * from salespersons
select * from Date_Dim

------------------------------------------------------------------>Data Validation

SELECT 'Sales' AS Table_Name, COUNT(*) AS Total_Rows
FROM Sales

UNION ALL

SELECT 'Customers', COUNT(*)
FROM Customers

UNION ALL

SELECT 'Products', COUNT(*)
FROM Products

UNION ALL

SELECT 'Stores', COUNT(*)
FROM Stores

UNION ALL

SELECT 'Salespersons', COUNT(*)
FROM Salespersons

UNION ALL

SELECT 'Targets', COUNT(*)
FROM Targets
--->Checking Null Values
select * from Sales
where Order_ID is null
or Customer_ID is null
or Product_ID is null
or Salesperson_ID is null
---->Checking Duplicates
select order_id, COUNT(*) as duplicates from Sales
group by Order_ID
having COUNT(*) > 1
----------------------------------------------------------------------------->Core KPI Queries
----->Total Sales (sales Amount = uni_price * quantity)(17144647.82)
select SUM(Unit_Price * quantity) as total_sales from sales
----->Total Profit (profit = total_sales - unit_price)(40049905.1700)
SELECT 
    SUM((s.Quantity * s.Unit_Price) - s.Discount - s.Shipping_Cost - (s.Quantity * p.unit_Cost)) AS Total_Profit
FROM Sales as s
JOIN 
Products as p 
ON s.Product_ID = p.Product_ID

--->Total orders(1200)
select COUNT(distinct order_id) as total_orders from sales
--->Total Customers(150)
select COUNT(distinct customer_id) as total_customers from Sales
--->Average Order Value(142867.12666)
select SUM((Unit_Price * quantity) - Discount) /COUNT(distinct order_id) as Average_Order_Value 
from sales
--->Profit margin(23.550000)
SELECT 
    ROUND(
        SUM(((s.Quantity * s.Unit_Price) - s.Discount) - (s.Quantity * p.unit_cost)) * 100.0
        / NULLIF(SUM((s.Quantity * s.Unit_Price) - s.Discount), 0),
        2
    ) AS Profit_Margin_Percentage
FROM Sales as s
JOIN Products as p 
ON s.Product_ID = p.Product_ID 


---------------------------------------------------------------------->Sales Trend Analysis
--->Monthly sales trend
SELECT
    YEAR(s.Order_Date) AS Sales_Year,
    MONTH(s.Order_Date) AS Sales_Month,
    SUM((s.Quantity * s.Unit_Price) - s.Discount) AS Total_Sales,
    SUM((s.Quantity * s.Unit_Price) - s.Discount - (s.Quantity * p.unit_cost)) AS Total_Profit
FROM Sales as s
	JOIN Products as  p 
	ON s.Product_ID = p.Product_ID
GROUP BY
    YEAR(s.Order_Date),
    MONTH(s.Order_Date)
ORDER BY
    Sales_Year,
    Sales_Month
--->Yearly Sales Trend
SELECT
	YEAR(s.Order_date) as sales_year,
	SUM((s.quantity * s.unit_price) - s.Discount) as total_sales,
	SUM((s.quantity *s.unit_price) - s.discount - (s.quantity * p.unit_cost)) as total_profit
	from sales as s
	join
	products as p
	on s.product_id = p.Product_ID
group by YEAR(s.Order_Date)
order by sales_year
--------------------------------------------------------------------------->Regional Performance
-->region wise total sales and total profits
SELECT st.region,
	SUM((s.quantity * s.unit_price) - s.Discount) as total_sales,
	SUM((s.quantity *s.unit_price) - s.discount - (s.quantity * p.unit_cost)) as total_profit
	from sales as s
	join
	products as p
	on s.product_id = p.Product_ID
	join
	Stores as st
	on s.Store_ID = st.Store_ID
group by st.Region
order by total_sales desc
---> Region Wise Profit Margin
SELECT st.region,
	SUM((s.quantity * s.unit_price) - s.Discount) as total_sales,
	SUM((s.quantity *s.unit_price) - s.discount - (s.quantity * p.unit_cost)) as total_profit,
	ROUND(
		SUM((s.quantity *s.unit_price) - s.discount - (s.quantity * p.unit_cost)) * 100.0 /
			nullif(SUM((s.quantity * s.unit_price) - s.Discount),0),2) as profit_margin
	from sales as s
	join
	products as p
	on s.product_id = p.Product_ID
	join
	Stores as st
	on s.Store_ID = st.Store_ID
group by st.Region
order by profit_margin desc
-------------------------------------------------------------------------------> PRODUCT ANALYSIS
--->Category-Wise Sales
SELECT p.category,
	SUM((s.quantity * s.unit_price) - s.Discount) as total_sales,
	SUM((s.quantity *s.unit_price) - s.discount - (s.quantity * p.unit_cost)) as total_profit
	from sales as s
	join Products as p
	on s.Product_ID = p.Product_ID
group by p.Category
order by total_sales desc
--->Top 10 Products by Sales
SELECT Top 10 p.product_id,p.product_name,
	SUM((s.quantity * s.unit_price) - s.Discount) as total_sales,
	SUM((s.quantity *s.unit_price) - s.discount - (s.quantity * p.unit_cost)) as total_profit
	from sales as s
	join Products as p
	on s.Product_ID = p.Product_ID
group by p.Product_ID,p.Product_Name
order by total_sales desc
--->Top 10 Products by Profit
SELECT Top 10 p.product_id,p.product_name,
	SUM((s.quantity * s.unit_price) - s.Discount) as total_sales,
	SUM((s.quantity *s.unit_price) - s.discount - (s.quantity * p.unit_cost)) as total_profit
	from sales as s
	join Products as p
	on s.Product_ID = p.Product_ID
group by p.Product_ID,p.Product_Name
order by total_profit desc
---------------------------------------------------------------------------->Store Performance
select st.store_id,st.store_name,st.store_type,st.city,st.state,st.region,
		SUM((s.quantity * s.unit_price) - s.Discount) as total_sales,
		SUM((s.quantity *s.unit_price) - s.discount - (s.quantity * p.unit_cost)) as total_profit,
		COUNT(Distinct s.Order_ID) as total_orders
	from Sales as s
	join Products as p
	on s.Product_ID = p.Product_ID
	join
	Stores as st
	on s.Store_ID = st.Store_ID
group by st.store_id,st.store_name,st.store_type,st.city,st.state,st.region
order by total_sales desc
--------------------------------------------------------------------------->Salesperson Performance
select sp.salesperson_id,sp.salesperson_name,
		SUM((s.quantity * s.unit_price) - s.Discount) as total_sales,
		SUM((s.quantity *s.unit_price) - s.discount - (s.quantity * p.unit_cost)) as total_profit,
		COUNT(Distinct s.Order_ID) as total_orders
	from Sales as s
	join Products as p
	on s.Product_ID = p.Product_ID
	join
	Salespersons as sp
	on s.Store_ID = sp.Salesperson_id
group by sp.salesperson_id,sp.salesperson_name
order by total_sales desc
------------------------------------------------------------------------------>Target VS Actual sales

SELECT
    sp.Salesperson_ID,
    sp.Salesperson_Name,
    SUM((s.quantity * s.unit_price) - s.Discount) AS Actual_Sales,
    SUM(t.sales_target) AS Sales_Target,
    SUM((s.quantity * s.unit_price) - s.Discount) - SUM(t.sales_target) AS Variance,
    ROUND(
        SUM((s.quantity * s.unit_price) - s.Discount) * 100.0 /
        NULLIF(SUM(t.sales_target), 0),
        2
    ) AS Target_Achievement_Percentage
FROM Sales s
JOIN Salespersons sp
    ON s.Salesperson_ID = sp.Salesperson_ID
JOIN Targets t
    ON sp.Salesperson_ID = t.Salesperson_ID
GROUP BY
    sp.Salesperson_ID,
    sp.Salesperson_Name
ORDER BY Target_Achievement_Percentage DESC
------------------------------------------------------------------------->Customer Analysis
--->Top customers by sales
select top 10 c.customer_id,c.customer_name,
		SUM((s.quantity * s.unit_price) - s.Discount) as total_sales,
		SUM((s.quantity *s.unit_price) - s.discount - (s.quantity * p.unit_cost)) as total_profit,
		COUNT(Distinct s.Order_ID) as total_orders
	from Sales as s
	join Products as p
	on s.Product_ID = p.Product_ID
	join customers as c
	on s.Customer_ID = c.Customer_ID
group by c.customer_id,c.customer_name
order by total_sales desc
--->Customer Wise Order Value
select top 10 c.customer_id,c.customer_name,
		COUNT(Distinct s.Order_ID) as total_orders,	
		SUM((s.quantity * s.unit_price) - s.Discount) as total_sales,
		SUM((s.quantity *s.unit_price) - s.discount) / NULLIF(COUNT(Distinct s.Order_ID),0) as Average_order_value
	from Sales as s
	join Products as p
	on s.Product_ID = p.Product_ID
	join customers as c
	on s.Customer_ID = c.Customer_ID
group by c.customer_id,c.customer_name
order by total_sales desc
---------------------------------------------------------------------->City-Wise Performance
select st.state,st.city,
	SUM((s.quantity * s.unit_price) - s.discount) as total_sales,
	SUM((s.quantity *s.unit_price) - s.discount - (s.quantity * p.unit_cost)) as total_profit,
	COUNT(Distinct s.Order_ID) as total_orders
	from Sales as s
	join Products as p
	on s.Product_ID = p.Product_ID
	join stores as st
	on s.store_id = st.store_id
group by st.city,st.state
order by total_sales desc
------------------------------------------------------------------>Best selling Product in each category
WITH ProductSales AS
(
    SELECT
        p.Category,
        p.Product_ID,
        p.Product_Name,
        SUM(s.Quantity * s.Unit_Price) AS Total_Sales,
        dense_RANK() OVER
        (
            PARTITION BY p.Category
            ORDER BY SUM(s.Quantity * s.Unit_Price) DESC
        ) AS Product_Rank
    FROM Sales s
    JOIN Products p
        ON s.Product_ID = p.Product_ID
    GROUP BY
        p.Category,
        p.Product_ID,
        p.Product_Name
)
SELECT
    Category,
    Product_ID,
    Product_Name,
    Total_Sales
FROM ProductSales
WHERE Product_Rank = 1
ORDER BY Category
----------------------------------------------------------------------------->Low performing products
SELECT
    p.Product_ID,
    p.Product_Name,
    p.Category,
    SUM((s.quantity * s.unit_price) - s.discount) as total_sales,
	SUM((s.quantity *s.unit_price) - s.discount - (s.quantity * p.unit_cost)) as total_profit
FROM Sales s
JOIN Products p
    ON s.Product_ID = p.Product_ID
GROUP BY
    p.Product_ID,
    p.Product_Name,
    p.Category
ORDER BY Total_Profit ASC
--------------------------------------------------------------------------------->Salesperson Ranking
SELECT
    sp.Salesperson_ID,
    sp.Salesperson_Name,
    SUM(s.Quantity * s.Unit_Price) AS Total_Sales,
    RANK() OVER
    (
        ORDER BY SUM(s.Quantity * s.Unit_Price) DESC
    ) AS Sales_Rank
FROM Sales s
JOIN Salespersons sp
    ON s.Salesperson_ID = sp.Salesperson_ID
GROUP BY
    sp.Salesperson_ID,
    sp.Salesperson_Name
ORDER BY Sales_Rank




	

